import * as THREE from 'three';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import RAPIER from './vendor/rapier.js';
import {headingMotion,movementFacing,firstPersonMotion} from './facing.js';
import {buildImaginationWorld,IMAGINATION_START,IDEA_SPARKS,IMAGINATION_EXIT} from './imagination-world.js?v=15';

const $=s=>document.querySelector(s),message=s=>$('#message').textContent=s,fixed=1/60;
const state={ready:false,paused:false,fp:false,fpBasis:null,run:false,yaw:0,facing:0,pitch:.12,mx:0,my:0,vy:0,grounded:false,jump:false,time:0,sparks:0,bridge:false,won:false};
const keys=new Set(),barriers=[],clock=new THREE.Clock();let renderer,scene,camera,world,body,collider,controller,player,imagination,brush,mini,miniCam,stickId=null,lookId=null,lookX=0,lookY=0,acc=0,miniTime=0;

function stop(){state.fpBasis=null;state.mx=state.my=0;keys.clear();stickId=lookId=null;$('#knob').style.transform=''}
function pause(value){state.paused=value;$('#paused').hidden=!value;stop();clock.getDelta()}
function updateHUD(){
 $('#score').textContent='ניצוצות '+state.sparks+'/3';document.querySelectorAll('#progress i').forEach((dot,i)=>dot.classList.toggle('active',i<state.sparks));
 if(state.won)$('#objective').textContent='שלב 1 הושלם · שער הקשת נפתח';
 else if(state.sparks<3)$('#objective').textContent='אספו שלושה ניצוצות רעיון · '+state.sparks+'/3';
 else if(!state.bridge)$('#objective').textContent='התקרבו לנהר הצבע וציירו גשר';
 else $('#objective').textContent='חצו את הגשר והגיעו לשער הקשת';
}
function reset(){const p=IMAGINATION_START;body.setTranslation(p,true);body.setNextKinematicTranslation(p);state.yaw=state.facing=state.vy=0;state.pitch=.12;state.sparks=0;state.bridge=state.won=false;imagination.reset();$('#win').hidden=true;updateHUD();pause(false);message('שליו: שלושה ניצוצות רעיון מתחבאים בין הציורים החיים!')}
function cameraMode(){if(!state.ready)return;stop();state.fp=!state.fp;if(state.fp)state.yaw=state.facing;player.visible=!state.fp;$('#view').textContent=state.fp?'גוף שלישי':'גוף ראשון';message(state.fp?'מבט מעיני סבא בעולם הדמיון':'גוף שלישי · סבא פונה לכיוון התנועה')}
$('#view').onclick=cameraMode;$('#pause').onclick=()=>pause(!state.paused);$('#resume').onclick=()=>pause(false);$('#reset').onclick=reset;$('#retry').onclick=()=>location.reload();
$('#again').onclick=()=>location.reload();$('#explore').onclick=()=>{$('#win').hidden=true;pause(false)};
$('#run').onclick=()=>{state.run=!state.run;$('#run').setAttribute('aria-pressed',String(state.run))};$('#jump').onclick=()=>state.jump=true;
$('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#game').requestFullscreen()}catch{message('אפשר לשחק גם ללא מסך מלא.')}};
$('#help').onclick=()=>{const p=body.translation();if(state.sparks<3){let nearest=null,distance=Infinity;imagination.sparks.forEach((s,i)=>{if(!s.visible)return;const d=s.position.distanceTo(new THREE.Vector3(p.x,p.y,p.z));if(d<distance){distance=d;nearest=i}});message(nearest==null?'שליו: כל הניצוצות נאספו.':'שליו: הניצוץ הקרוב נמצא '+(IDEA_SPARKS[nearest][2]<p.z?'קדימה לכיוון שער הקשת.':'מאחוריך — הסתובב וחפש אור צבעוני.'));return}if(!state.bridge){message('שליו: עמוד במרכז שפת נהר הצבע ולחץ על המכחול.');return}message('שליו: הגשר מוכן! המשך ישר דרך הציורים החיים אל שער הקשת.');};

function paintBridge(){if(!state.ready||state.paused)return;if(state.bridge){message('הגשר כבר מצויר — אפשר לחצות!');return}if(state.sparks<3){message('שליו: חסרים עוד '+(3-state.sparks)+' ניצוצות רעיון.');return}const p=body.translation();if(Math.abs(p.x)>7||p.z>4||p.z<-2){message('שליו: התקרב למרכז שפת נהר הצבע.');return}state.bridge=imagination.createBridge();brush.rotation.z=-1.25;setTimeout(()=>brush.rotation.z=-.4,180);updateHUD();message('שליו: המכחול הפך את הרעיונות לגשר אמיתי!')}
$('#brush').onclick=paintBridge;
function magicAdvance(){if(!state.ready||state.paused)return;imagination.sparks.forEach(s=>s.visible=false);state.sparks=3;if(!state.bridge){imagination.createBridge();state.bridge=true}body.setTranslation({x:0,y:1.1,z:-54},true);body.setNextKinematicTranslation({x:0,y:1.1,z:-54});updateHUD();message('קסם! אספנו את הניצוצות וציירנו את הגשר. שער הקשת לפנינו!')}
$('#magic').onclick=magicAdvance;

const stick=$('#stick');stick.onpointerdown=e=>{if(state.paused)return;stickId=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)};
function moveStick(e){if(e.pointerId!==stickId)return;const r=stick.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,l=Math.max(32,Math.hypot(x,y));state.mx=x/l;state.my=-y/l;$('#knob').style.transform=`translate(${state.mx*27}px,${-state.my*27}px)`}
stick.onpointermove=moveStick;stick.onpointerup=stick.onpointercancel=stick.onlostpointercapture=()=>{state.fpBasis=null;state.mx=state.my=0;stickId=null;$('#knob').style.transform=''};
const canvas=$('#scene');canvas.onpointerdown=e=>{if(state.paused)return;lookId=e.pointerId;lookX=e.clientX;lookY=e.clientY;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(e.pointerId!==lookId)return;const d=-(e.clientX-lookX)*.005;state.yaw+=d;if(state.fp){state.facing=state.yaw;if(state.fpBasis!=null)state.fpBasis+=d}state.pitch=THREE.MathUtils.clamp(state.pitch+(e.clientY-lookY)*.004,-.8,.85);lookX=e.clientX;lookY=e.clientY};canvas.onpointerup=canvas.onpointercancel=()=>lookId=null;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space')state.jump=true;if(e.code==='KeyK'&&!e.repeat)magicAdvance();if(e.code==='KeyB'&&!e.repeat)paintBridge();if(e.code==='Escape')pause(!state.paused)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.ready)pause(true)});

async function loadModel(url,height){const gltf=await new GLTFLoader().loadAsync(url),root=gltf.scene,b=new THREE.Box3().setFromObject(root),size=b.getSize(new THREE.Vector3()),center=b.getCenter(new THREE.Vector3()),scale=height/size.y;root.scale.setScalar(scale);root.position.set(-center.x*scale,-b.min.y*scale,-center.z*scale);root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});const wrapper=new THREE.Group();wrapper.add(root);return wrapper}

async function init(){
 await RAPIER.init();renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.15));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(62,1,.08,260);
 scene.add(new THREE.HemisphereLight(0xfff5de,0x7d62a8,3));const sun=new THREE.DirectionalLight(0xffe8ba,3.4);sun.position.set(-18,28,16);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-38,right:38,top:38,bottom:-38,far:100});scene.add(sun);
 for(const [x,y,z,c] of [[-20,8,22,0xff76b7],[19,10,-28,0x62d9ff],[0,8,-60,0xb979ff]]){const l=new THREE.PointLight(c,6,34,2);l.position.set(x,y,z);scene.add(l)}
 world=new RAPIER.World({x:0,y:-20,z:0});world.timestep=fixed;imagination=buildImaginationWorld({scene,world,RAPIER,barriers});
 body=world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(IMAGINATION_START.x,IMAGINATION_START.y,IMAGINATION_START.z));collider=world.createCollider(RAPIER.ColliderDesc.capsule(.6,.35),body);controller=world.createCharacterController(.03);controller.enableAutostep(.25,.2,true);controller.enableSnapToGround(.3);
 $('#loadtext').textContent='מעירים את הציורים ואת סבא ושליו…';player=await loadModel('./assets/hero.glb',2.2);const visual=new THREE.Group(),raw=player.children[0];player.remove(raw);visual.add(raw);visual.rotation.y=Math.PI;player.add(visual);scene.add(player);brush=new THREE.Mesh(new THREE.CylinderGeometry(.04,.04,.85,8),stdBrush());brush.rotation.z=-.4;brush.position.set(.5,1.08,-.2);player.add(brush);
 miniCam=new THREE.PerspectiveCamera(48,1.75,.2,100);miniCam.position.set(13,10,-48);miniCam.lookAt(0,3,-62);mini=new THREE.WebGLRenderer({canvas:$('#gateView'),antialias:false});mini.setPixelRatio(1);mini.setSize(140,80,false);
 function resize(){renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}resize();window.addEventListener('resize',resize);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();state.paused=true;fail('התצוגה נעצרה. טען שוב כדי להמשיך.')});
 state.ready=true;$('#loading').hidden=true;updateHUD();message('שליו: זה גן הציורים החיים! נמצא שלושה ניצוצות ונצייר גשר.');clock.start();frame();
}
function stdBrush(){return new THREE.MeshStandardMaterial({color:0xd29a5c,roughness:.65})}
function collect(){const p=new THREE.Vector3(body.translation().x,body.translation().y,body.translation().z);imagination.sparks.forEach((spark,i)=>{if(!spark.visible||spark.position.distanceTo(p)>1.45)return;spark.visible=false;state.sparks++;updateHUD();message(state.sparks===3?'שליו: כל הניצוצות אצלנו! עכשיו נצייר גשר.':'שליו: ניצוץ רעיון נאסף! נשארו '+(3-state.sparks)+'.')})}
function step(){let x=state.mx+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),z=state.my+(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0);if(Math.hypot(x,z)<.12)x=z=0;const len=Math.max(1,Math.hypot(x,z));x/=len;z/=len;const speed=state.run||keys.has('ShiftLeft')?7:4,m=state.fp?firstPersonMotion(state,x,z,speed):headingMotion(state.yaw,x,z,speed);if(!state.fp&&Math.hypot(m.x,m.z)>.01)state.facing=movementFacing(m.x,m.z);if(state.jump&&state.grounded)state.vy=8;state.jump=false;state.vy-=20*fixed;controller.computeColliderMovement(collider,{x:m.x*fixed,y:state.vy*fixed,z:m.z*fixed});const p=body.translation(),d=controller.computedMovement();body.setNextKinematicTranslation({x:p.x+d.x,y:p.y+d.y,z:p.z+d.z});state.grounded=controller.computedGrounded();if(state.grounded&&state.vy<0)state.vy=0;world.step();collect();const now=body.translation();if(now.y<-4){body.setTranslation(IMAGINATION_START,true);body.setNextKinematicTranslation(IMAGINATION_START);state.vy=0;message('שליו: נהר הצבע עמוק! חזרנו לדף הראשון.')}if(!state.won&&state.bridge&&Math.hypot(now.x-IMAGINATION_EXIT[0],now.z-IMAGINATION_EXIT[2])<5){state.won=true;updateHUD();$('#win').hidden=false;message('שליו: עברנו דרך שער הקשת! שלב הדמיון הראשון הושלם.');pause(true)}}
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(!state.paused){state.time+=dt;imagination.animate(dt,state.time);acc+=dt;while(acc>=fixed){step();acc-=fixed}}const p=body.translation();player.position.set(p.x,p.y-.95,p.z);player.rotation.y=state.facing;player.position.y+=Math.sin(state.time*2)*.018;const eye=new THREE.Vector3(p.x,p.y+.7,p.z),forward=new THREE.Vector3(-Math.sin(state.yaw)*Math.cos(state.pitch),-Math.sin(state.pitch),-Math.cos(state.yaw)*Math.cos(state.pitch));if(state.fp){camera.position.copy(eye);camera.lookAt(eye.clone().add(forward))}else{const desired=eye.clone().addScaledVector(forward,-5.5);desired.y+=1.2;const delta=desired.clone().sub(eye),hit=new THREE.Raycaster(eye,delta.clone().normalize(),0,delta.length()).intersectObjects(barriers,true)[0];camera.position.copy(hit?eye.clone().addScaledVector(delta.normalize(),Math.max(.4,hit.distance-.35)):desired);camera.position.y=Math.max(.55,camera.position.y);camera.lookAt(eye.clone().addScaledVector(forward,2))}renderer.render(scene,camera);miniTime+=dt;if(miniTime>.35){mini.render(scene,miniCam);miniTime=0}}
function fail(text){$('#loading').hidden=false;$('#loadtext').textContent=text;$('#retry').hidden=false}
init().catch(error=>{console.error(error);fail('לא הצלחנו לטעון את עולם היצירה והדמיון. נסה שוב.')});
